code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the smallest fully observed repeating tile consistent with all
    # non-background cells. Zero cells are the missing parts of the pattern.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    best = None
    for ph in range(1, h + 1):
        for pw in range(1, w + 1):
            tile = {}
            ok = True
            for r, c, v in cells:
                key = (r % ph, c % pw)
                if key in tile and tile[key] != v:
                    ok = False
                    break
                tile[key] = v
            if not ok or len(tile) != ph * pw:
                continue
            score = (ph * pw, ph + pw, ph, pw)
            if best is None or score < best[0]:
                best = (score, ph, pw, tile)
    if best is None:
        # Fallback: use the smallest period in row signatures.
        for p in range(1, h + 1):
            vals = {}
            good = True
            for r in range(h):
                rowvals = {v for v in grid[r] if v != 0}
                if len(rowvals) > 1:
                    good = False
                    break
                if rowvals:
                    v = next(iter(rowvals))
                    if r % p in vals and vals[r % p] != v:
                        good = False
                        break
                    vals[r % p] = v
            if good and len(vals) == p:
                return [[vals[r % p] for _ in range(w)] for r in range(h)]
        return [row[:] for row in grid]
    _, ph, pw, tile = best
    return [[tile[(r % ph, c % pw)] for c in range(w)] for r in range(h)]
'''
